def main():
    OUT.mkdir(parents=True, exist_ok=True)
    for i, lang in enumerate(LANGUAGES):
        table = {row[0]: row[i + 1] for row in T}
        assert all(len(row) == 9 for row in T), [row[0] for row in T if len(row) != 9]
        (OUT / f"{lang}.json").write_text(json.dumps(table, ensure_ascii=False, indent="\t") + "\n", encoding="utf-8")
    print(f"{len(T)} texts x {len(LANGUAGES)} languages -> {OUT}")


if __name__ == "__main__":
    main()
